function validate([root, queries]) {
  if (!Array.isArray(root) || root.length === 0 || root[0] === null) return 'The tree needs at least two nodes.';
  const values = root.filter(v => v !== null);
  if (values.length < 2 || values.length > 100000) return 'The tree has between 2 and 10^5 nodes.';
  if (values.some(v => !Number.isInteger(v) || v < 1 || v > 1000000)) return 'Each node value is a whole number from 1 to 10^6.';
  if (!Array.isArray(queries) || queries.length < 1 || queries.length > 100000) return 'queries has between 1 and 10^5 numbers.';
  if (queries.some(q => !Number.isInteger(q) || q < 1 || q > 1000000)) return 'Each query is a whole number from 1 to 10^6.';
  // Rebuild the links from the level order; an in-order walk must then give strictly rising values.
  const nodes = [{ val: root[0], left: null, right: null }];
  let next = 1;
  for (let q = 0; q < nodes.length && next < root.length; q++) {
    for (const side of ['left', 'right']) {
      if (next >= root.length) break;
      const value = root[next++];
      if (value === null) continue;
      const child = { val: value, left: null, right: null };
      nodes[q][side] = child;
      nodes.push(child);
    }
  }
  if (next < root.length) return 'Every value after the root needs a parent node.';
  const stack = [];
  let node = nodes[0], last = -Infinity;
  while (node || stack.length) {
    while (node) { stack.push(node); node = node.left; }
    node = stack.pop();
    if (node.val <= last) return 'The tree must be a binary search tree with distinct values.';
    last = node.val;
    node = node.right;
  }
  return null;
}

