function closestNodes(root, queries) {
  const sorted = [];
  const stack = [];
  let node = root;
  while (node || stack.length > 0) {
    while (node) {
      stack.push(node);
      node = node.left;
    }
    node = stack.pop();
    sorted.push(node.val);
    node = node.right;
  }

  const answer = [];
  for (const query of queries) {
    let left = 0;
    let right = sorted.length;
    while (left < right) {
      const mid = (left + right) >> 1;
      if (sorted[mid] < query) {
        left = mid + 1;
      } else {
        right = mid;
      }
    }
    const ceiling = left < sorted.length ? sorted[left] : -1;
    let floor = left > 0 ? sorted[left - 1] : -1;
    if (ceiling === query) {
      floor = query;
    }
    answer.push([floor, ceiling]);
  }
  return answer;
}

