function closestNodes(root, queries) {
  const values = [];
  const collect = (node) => {
    if (!node) return;
    values.push(node.val);
    collect(node.left);
    collect(node.right);
  };
  collect(root);
  return queries.map(q => {
    let low = -1, high = -1;
    for (const v of values) {
      if (v <= q && (low === -1 || v > low)) low = v;
      if (v >= q && (high === -1 || v < high)) high = v;
    }
    return [low, high];
  });
}

