function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const small = size === 'small';
  for (;;) {
    const count = small ? pick(2, 10) : pick(850, 950);
    const top = small ? (rand() < 0.7 ? 25 : 1000000) : 1000000;
    // Distinct values inserted in random order give a random BST shape.
    const seen = new Set();
    const order = [];
    while (order.length < count) {
      const value = pick(1, top);
      if (seen.has(value)) continue;
      seen.add(value);
      order.push(value);
    }
    // Sometimes insert in sorted order to build a chain.
    if (rand() < (small ? 0.2 : 0.1)) { const rising = rand() < 0.5; order.sort((a, b) => (rising ? a - b : b - a)); }
    let root = null;
    for (const value of order) {
      const fresh = { val: value, left: null, right: null };
      if (!root) { root = fresh; continue; }
      let at = root;
      for (;;) {
        const side = value < at.val ? 'left' : 'right';
        if (!at[side]) { at[side] = fresh; break; }
        at = at[side];
      }
    }
    const tree = [];
    const queue = [root];
    for (let q = 0; q < queue.length; q++) {
      const at = queue[q];
      tree.push(at ? at.val : null);
      if (at) queue.push(at.left, at.right);
    }
    while (tree[tree.length - 1] === null) tree.pop();
    if (tree.length > 2000) continue;
    // Queries: tree values, their neighbours, and random numbers, including values past either end.
    const qCount = small ? pick(1, 8) : 2000;
    const queries = [];
    for (let i = 0; i < qCount; i++) {
      const style = rand();
      let query;
      if (style < 0.3) query = order[pick(0, order.length - 1)];
      else if (style < 0.5) query = order[pick(0, order.length - 1)] + pick(-1, 1);
      else if (style < 0.6) query = rand() < 0.5 ? 1 : 1000000;
      else query = pick(1, Math.min(1000000, top + 5));
      queries.push(Math.min(1000000, Math.max(1, query)));
    }
    return [tree, queries];
  }
}
